import "./testimonial.css";

export interface TestimonialProps {
  quote: string;
  name: string;
  role: string;
  avatarSrc: string;
  layout: "centered" | "card" | "large";
  tone: "light" | "white" | "accent" | "dark";
}

export function TestimonialRender({ quote, name, role, avatarSrc, layout, tone }: TestimonialProps) {
  return (
    <div className="p1-testimonial p1-block" data-layout={layout} data-tone={tone}>
      <div className="p1-testimonial__inner">
        <div className="p1-testimonial__mark" aria-hidden="true">&ldquo;</div>
        <p className="p1-testimonial__quote">{quote}</p>
        <div className="p1-testimonial__attribution">
          <div className="p1-testimonial__avatar">
            {avatarSrc && <img src={avatarSrc} alt={name} className="p1-testimonial__avatar-img" />}
          </div>
          <div className="p1-testimonial__byline">
            <div className="p1-testimonial__name">{name}</div>
            <div className="p1-testimonial__role">{role}</div>
          </div>
        </div>
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta, wireframe } from '../define-meta';
import { TestimonialRender, type TestimonialProps } from "./testimonial";
export type { TestimonialProps };

export const TestimonialBlock: ComponentConfig<TestimonialProps> = {
  fields: {
    quote: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "A genuine-sounding customer quote, 15–35 words. First person." },
    },
    name: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Customer's full name." },
    },
    role: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Job title and company. E.g. Operations Lead, Acme Corp." },
    },
    avatarSrc: {
      type: "text" as const,
      ai: { exclude: true },
    },
    layout: {
      type: "select" as const,
      options: [
        { label: "Centered", value: "centered" },
        { label: "Card", value: "card" },
        { label: "Large", value: "large" },
      ],
    },
    tone: {
      type: "select" as const,
      options: [
        { label: "Light", value: "light" },
        { label: "White", value: "white" },
        { label: "Accent", value: "accent" },
        { label: "Dark", value: "dark" },
      ],
    },
  },
  defaultProps: {
    quote: "The team was up and running in a day, and we haven't looked back. It just works.",
    name: "Jordan Ellis",
    role: "Operations Lead",
    avatarSrc: wireframe(200, 200),
    layout: "centered",
    tone: "light",
  },
  render: TestimonialRender,
};

export const meta = defineMeta({
  title: 'Testimonial',
  description: 'Customer testimonial with quote text, name, role, and avatar in centered/card/large layouts and multiple tones; use for social proof.',
  categories: ["trust"],
  published: true,
});

.p1-testimonial[data-tone="light"] { background-color: var(--p1-surface-subtle); }
.p1-testimonial[data-tone="accent"] {
  background-color: var(--p1-accent);
  color: var(--p1-fg-inverse);
}
.p1-testimonial[data-tone="dark"] {
  background-color: var(--p1-surface-inverse);
  color: var(--p1-fg-inverse);
}

.p1-testimonial__inner {
  display: flex;
  flex-direction: column;
  gap: var(--p1-space-lg);
  margin-inline: auto;
}
.p1-testimonial[data-layout="large"] .p1-testimonial__inner { max-inline-size: var(--p1-container-narrow); }
.p1-testimonial:not([data-layout="large"]) .p1-testimonial__inner { max-inline-size: 48rem; }

.p1-testimonial:not([data-layout="card"]) .p1-testimonial__inner { text-align: center; }

.p1-testimonial__mark {
  font-size: 5rem;
  font-style: italic;
  font-weight: 800;
  line-height: 0.5;
}
.p1-testimonial[data-tone="light"] .p1-testimonial__mark,
.p1-testimonial[data-tone="white"] .p1-testimonial__mark {
  color: var(--p1-accent);
}
.p1-testimonial[data-tone="accent"] .p1-testimonial__mark,
.p1-testimonial[data-tone="dark"] .p1-testimonial__mark {
  color: var(--p1-warning);
}

.p1-testimonial__quote {
  font-size: var(--p1-text-2xl);
  font-style: italic;
  font-weight: var(--p1-weight-medium);
  line-height: var(--p1-leading-tight);
  margin: 0;
  text-wrap: balance;
}
.p1-testimonial[data-layout="large"] .p1-testimonial__quote { font-size: var(--p1-text-3xl); }

.p1-testimonial__attribution {
  align-items: center;
  display: flex;
  gap: var(--p1-space-sm);
}
.p1-testimonial:not([data-layout="card"]) .p1-testimonial__attribution { justify-content: center; }

.p1-testimonial__avatar {
  background-color: color-mix(in oklch, var(--p1-fg-default) 10%, transparent);
  block-size: 3rem;
  border-radius: var(--p1-radius-pill);
  flex: none;
  inline-size: 3rem;
  overflow: hidden;
}
.p1-testimonial__avatar-img { block-size: 100%; inline-size: 100%; object-fit: cover; }

.p1-testimonial__byline { text-align: start; }
.p1-testimonial__name { font-weight: var(--p1-weight-bold); }
.p1-testimonial__role {
  font-size: var(--p1-text-sm);
  color: var(--p1-fg-muted);
}
.p1-testimonial[data-tone="accent"] .p1-testimonial__role,
.p1-testimonial[data-tone="dark"] .p1-testimonial__role {
  color: var(--p1-fg-inverse-muted);
}

